<section class="inner-hero notices-hero"><div class="container"><span class="eyebrow">Information desk</span><h1>Notices &<br><em>announcements.</em></h1><p>Official updates, admission schedules, student information and campus announcements.</p></div></section><section class="section notices-page"><div class="container"><form class="notice-filters" method="get"><label><span class="sr-only">Search notices</span><input name="q" value="<?= e($search) ?>" placeholder="Search notices…"></label><label><span class="sr-only">Notice category</span><select name="category"><option value="">All categories</option><?php foreach($categories as $option):?><option value="<?= e($option) ?>"<?= selected($category,$option) ?>><?= e($option) ?></option><?php endforeach?></select></label><button class="button button-primary">Filter</button><?php if($search||$category):?><a class="button button-outline" href="<?= url('notices') ?>">Clear</a><?php endif?></form><div class="notice-archive"><?php foreach($notices as $notice):?><a class="notice-row" href="<?= url('notices/'.$notice['slug']) ?>"><time><b><?= date('d',strtotime($notice['published_at'])) ?></b><span><?= strtoupper(date('M',strtotime($notice['published_at']))) ?><br><?= date('Y',strtotime($notice['published_at'])) ?></span></time><div><?php if($notice['is_pinned']):?><small class="pinned">Pinned</small><?php endif?><small><?= e($notice['category']) ?></small><h2><?= e($notice['title']) ?></h2><p><?= e($notice['excerpt']) ?></p></div><span class="notice-arrow">→</span></a><?php endforeach?></div><?php if(!$notices):?><div class="empty-public"><h2>No matching notices</h2><p>Try another keyword or remove the category filter.</p><a href="<?= url('notices') ?>">View all notices →</a></div><?php endif?></div></section>
